pub(crate) const INT_SIZE: i32 = 32 << (!(0 as u64) >> 63);
pub const MAX_INT: u64 = (1 << (INT_SIZE - 1)) - 1;
pub const MIN_INT: i64 = -1 << (INT_SIZE - 1);
pub const MAX_INT8: i32 = (1 << 7) - 1;
pub const MIN_INT8: i32 = -1 << 7;
pub const MAX_INT16: i32 = (1 << 15) - 1;
pub const MIN_INT16: i32 = -1 << 15;
pub const MAX_INT32: i64 = (1 << 31) - 1;
pub const MIN_INT32: i32 = -1 << 31;
pub const MAX_INT64: u64 = (1 << 63) - 1;
pub const MIN_INT64: i64 = -1 << 63;
pub const MAX_UINT: u128 = (1 << INT_SIZE) - 1;
pub const MAX_UINT8: i32 = (1 << 8) - 1;
pub const MAX_UINT16: i32 = (1 << 16) - 1;
pub const MAX_UINT32: i64 = (1 << 32) - 1;
pub const MAX_UINT64: u128 = (1 << 64) - 1;
